def invert_unique(mapping):
    inverted = {}
    for key, value in mapping.items():
        if value in inverted:
            raise ValueError(f"Duplicate value {value} found in mapping.")
        inverted.setdefault(value, []).append(key)
    return inverted

def even_position_sum(values):
    if not values:
        return 0
    return sum(values[i] for i in range(0, len(values), 2))
